INSERT INTO transcript_entries(rowid,id,person_id,chat_id,seq,turn_id,kind,text,activity,detail,details,refs,status,agent_item_id,revision,created_at,updated_at) VALUES(3,'01a12747-0dea-73c3-ac1b-d06aa2578755','asha','c-asha',3,'01a12747-0de1-7275-8a01-5d390007e89e','reply',unistr('Your August test from Sunrise Labs (collected 12 Aug) has two results marked **High**:\u000a\u000a- **HbA1c** 6.8 % (range 4.0 - 5.6)\u000a- **Glucose**, fasting, 118 mg/dL (range 70 - 99)\u000a\u000aCRP was <5 mg/L, inside its range. The lab later corrected the TSH from that sample to **4.6 mIU/L**, above its range of 0.4 - 4.0.\u000a\u000aThe HbA1c and the fasting glucose are worth going over together with your doctor.\u000a\u000a```rufi-basis\u000aFrom the record, read now: the results of the Sunrise Labs report collected on 12 Aug 2026, with the corrected TSH.\u000a```'),NULL,NULL,NULL,NULL,NULL,'01a12747-0de9-7004-95dc-a7f1ba8a797e',6,'2026-10-02T03:42:10.000Z','2026-10-02T03:42:10.000Z');
